pub fn simple_nested(a: &mut Vec<i32>, b: &Vec<i32>, N: i32) -> i32 {
    // Assumptions from the problem statement:
    // - N is non-negative and N <= 0x3FFF_FFFF
    // - a.len() == b.len() == N
    // - for each i in [0, N), b[i] is either i or i+1

    let n_usize = N as usize;
    debug_assert!(N >= 0);
    debug_assert!(a.len() == n_usize && b.len() == n_usize);

    let mut sum: i32 = 0;

    for i in 0..n_usize {
        let i_i32 = i as i32;
        let bi = b[i];

        let val = if bi == i_i32 {
            1
        } else {
            // Under the stated assumptions, the only other valid value is i+1.
            debug_assert!(bi == i_i32 + 1);
            2
        };

        a[i] = val;
        sum += val;
    }

    sum
}